const STORE = 'goldPreOpen.v1'

interface Saved { day: string; baseline: string; mcx: string; threshold: string; trigger: string; done: Record<string, boolean> }
const blank = (): Saved => ({ day: todayKey(), baseline: '', mcx: '', threshold: '300', trigger: '1.1161', done: {} })

function load(): Saved {
  try {
    const s = JSON.parse(localStorage.getItem(STORE) || 'null') as Saved | null
    if (!s) return blank()
    // Day-specific entries (close override, MCX price, ticks) reset each day; settings carry over.
    return s.day === todayKey() ? s : { ...blank(), threshold: s.threshold, trigger: s.trigger }
  } catch { return blank() }
}
