  if (!now) return { label: '—', color: T.muted }
  const d = now.getDay(), m = now.getHours() * 60 + now.getMinutes()
  if (d === 0 || d === 6) return { label: 'WEEKEND', color: T.muted }

function sessionState(now: Date | null): { label: string; color: string } {
  if (!now) return { label: '—', color: T.muted }
  const d = now.getDay(), m = now.getHours() * 60 + now.getMinutes()
  if (d === 0 || d === 6) return { label: 'WEEKEND', color: T.muted }
  if (m >= 9 * 60 && m < 9 * 60 + 15) return { label: 'PRE-OPEN', color: T.amber }
  if (m >= 9 * 60 + 15 && m < 15 * 60 + 30) return { label: 'NSE OPEN', color: T.green }
  if (m >= 15 * 60 + 30 && m < 16 * 60) return { label: 'CLOSING', color: T.amber }
  return { label: 'CLOSED', color: T.muted }
}

