function fmt(val: number | null | undefined, format: string): string {
  if (val === null || val === undefined) return '—'
  if (format === '%') return `${(val * 100).toFixed(2)}%`
  if (format === '.2f') return val.toFixed(2)
  return String(val)
}

function useFlash(price: number | undefined): 'up' | 'down' | null {
  const [flash, setFlash] = useState<'up' | 'down' | null>(null)
  const prev = useRef<number | undefined>(undefined)
  useEffect(() => {
    if (price === undefined) return
    if (prev.current !== undefined && price !== prev.current) {
      setFlash(price > prev.current ? 'up' : 'down')
      const id = setTimeout(() => setFlash(null), 800)
      prev.current = price
      return () => clearTimeout(id)
    }
    prev.current = price
  }, [price])
  return flash
}

