function nseTime(ts: string): number | null {
  const m = /^(\d{2})-(\w{3})-(\d{4}) (\d{2}):(\d{2})/.exec(ts)
  if (!m) return null
  const mon = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].indexOf(m[2])
  return mon < 0 ? null : Date.UTC(+m[3], mon, +m[1], +m[4], +m[5]) / 1000
}

