export function spanNote(v?: { prev_date?: string | null; market_date?: string | null } | null): string | null {
  if (!v?.prev_date || !v.market_date) return null
  const a = new Date(`${v.prev_date}T00:00:00Z`), b = new Date(`${v.market_date}T00:00:00Z`)
  let weekdays = 0
  for (const d = new Date(a); d < b; d.setUTCDate(d.getUTCDate() + 1)) if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) weekdays++
  return weekdays > 1 ? `since ${a.toLocaleDateString('en-IN', { weekday: 'short', timeZone: 'UTC' })}` : null
}

export function useSurveillance(symbols: string[]): Record<string, RiskFlags> {
  const key = [...new Set(symbols.map(s => s.toUpperCase()))].sort().join(',')
  const [flags, setFlags] = useState<Record<string, RiskFlags>>(() => memo.get(key)?.flags ?? {})
  useEffect(() => {
    if (!key) { setFlags({}); return }
    const hit = memo.get(key)
    if (hit && Date.now() - hit.at < 30 * 60_000) { setFlags(hit.flags); return }
    let live = true
    getSurveillance(key.split(',')).then(r => {
      memo.set(key, { at: Date.now(), flags: r.data.flags })
      if (live) setFlags(r.data.flags)
    }).catch(() => {})
    return () => { live = false }
  }, [key])
  return flags

export function useFinancialsLatest(symbols: string[], opts: { prefetch?: boolean } = {}): { fin: Record<string, FinLatest>; pending: number } {
  const prefetch = opts.prefetch ?? true
  const [fin, setFin] = useState<Record<string, FinLatest>>({})
  const key = [...new Set(symbols.map(s => s.toUpperCase()))].sort().join(',')
  useEffect(() => {
    const syms = key.split(',').filter(Boolean)
    if (!syms.length) { setFin({}); return }
    let live = true, tries = 0
    let iv: ReturnType<typeof setInterval> | null = null
    const load = () => getFinancialsLatest(syms).then(r => {
      if (!live) return
      setFin(r.data.latest)
      const missing = syms.filter(x => !r.data.latest[x])
      if (prefetch && tries === 0 && missing.length) prefetchFinancials(missing).catch(() => {})
      if ((!prefetch || !missing.length || ++tries > 12) && iv) { clearInterval(iv); iv = null }

